// IMPORTANT: This file contains a hand-written JS runtime that mirrors engine/executor.ts.
// It is NOT auto-generated. When adding a new node type or changing a node's data field names,
// update BOTH executor.ts AND the generated JS inside generateJS() below.
import type { Area, ElementData } from '@/types'
import type { Node, Edge } from '@vue-flow/core'
import type { ItemLayout } from '@/stores/layout'

interface SlimNode {
  id: string
  type: string
  data: Record<string, unknown>
}

interface SlimEdge {
  source: string
  target: string
  sourceHandle?: string | null
  targetHandle?: string | null
}

interface SlimGraph {
  nodes: SlimNode[]
  edges: SlimEdge[]
}

function slimGraph(nodes: Node[], edges: Edge[]): SlimGraph {
  return {
    nodes: nodes.map((n) => ({ id: n.id, type: n.type ?? '', data: { ...n.data } })),
    edges: edges.map((e) => ({
      source: e.source,
      target: e.target,
      sourceHandle: e.sourceHandle ?? null,
      targetHandle: e.targetHandle ?? null,
    })),
  }
}

export function generateHTML(areas: Area[]): string {
  const divs = areas
    .map((a) => {
      const style = `left:${a.x}%;top:${a.y}%;width:${a.width}%;height:${a.height}%;`
      return `  <div id="area-${a.id}" class="area" style="${style}"></div>`
    })
    .join('\n')
  return `<div id="overlay">\n${divs}\n</div>`
}

export function generateCSS(): string {
  return `@import url('https://cdnjs.cloudflare.com/ajax/libs/animate.css/4.1.1/animate.min.css');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: transparent;
  overflow: hidden;
  width: 100%;
  height: 100%;
}

#overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.area {
  position: absolute;
  overflow: hidden;
}

.content-item {
  position: absolute;
  overflow: hidden;
}

.content-item img,
.content-item video {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.text-content {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: sans-serif;
  font-size: 24px;
  color: white;
  text-shadow: 1px 1px 4px rgba(0, 0, 0, 0.8);
  white-space: pre-wrap;
  word-break: break-word;
  text-align: center;
}

@keyframes alchemy-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes alchemy-fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}

@keyframes alchemy-slide-left {
  from { transform: translateX(-100%); }
  to   { transform: translateX(0); }
}

@keyframes alchemy-slide-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}

@keyframes alchemy-slide-top {
  from { transform: translateY(-100%); }
  to   { transform: translateY(0); }
}

@keyframes alchemy-slide-bottom {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}`
}

export function generateJS(
  areas: Area[],
  graphs: Record<string, { nodes: Node[]; edges: Edge[] }>,
  layouts: Record<string, Record<string, ItemLayout>>,
  allElements: Record<string, ElementData[]>,
): string {
  const areaData = areas.map((a) => ({
    id: a.id, name: a.name, x: a.x, y: a.y, w: a.width, h: a.height,
  }))

  const graphData: Record<string, SlimGraph> = {}
  for (const [areaId, g] of Object.entries(graphs)) {
    graphData[areaId] = slimGraph(g.nodes, g.edges)
  }

  const layoutData: Record<string, Record<string, ItemLayout>> = {}
  for (const [parentId, items] of Object.entries(layouts)) {
    layoutData[parentId] = {}
    for (const [nodeId, l] of Object.entries(items)) {
      layoutData[parentId][nodeId] = { x: l.x, y: l.y, w: l.w, h: l.h, z: l.z }
    }
  }

  return `// Generated by Alchemy — paste into Streamlabs Custom Widget JS field
(function () {
  var AREAS = ${JSON.stringify(areaData, null, 2)};

  var GRAPHS = ${JSON.stringify(graphData, null, 2)};

  var LAYOUTS = ${JSON.stringify(layoutData, null, 2)};

  var ELEMENTS = ${JSON.stringify(allElements, null, 2)};

  var activeTimers = {};

  var WEB_SAFE_FONTS = new Set(['sans-serif','serif','monospace','cursive','fantasy',
    'Arial','Verdana','Tahoma','Trebuchet MS','Georgia',
    'Times New Roman','Courier New','Impact','Comic Sans MS']);

  function injectGoogleFonts() {
    var families = [];
    Object.values(ELEMENTS).forEach(function (els) {
      els.forEach(function (el) {
        if (el.type === 'text' && el.fontFamily && !WEB_SAFE_FONTS.has(el.fontFamily)) {
          if (families.indexOf(el.fontFamily) === -1) families.push(el.fontFamily);
        }
      });
    });
    families.forEach(function (family) {
      var link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=' + encodeURIComponent(family) + ':wght@100;200;300;400;500;600;700;800;900&display=swap';
      document.head.appendChild(link);
    });
  }

  injectGoogleFonts();

  console.log('[Alchemy] loaded. Areas:', AREAS.map(function(a){return a.id+' ('+a.name+')'}).join(', '));

  function outEdges(edges, nodeId) {
    return edges.filter(function (e) { return e.source === nodeId; });
  }

  function contentEdges(edges, nodeId) {
    return edges.filter(function (e) {
      return e.target === nodeId && e.targetHandle === 'content';
    });
  }

  var areaVars = {};

  function getAreaVars(areaId) {
    if (!areaVars[areaId]) areaVars[areaId] = {};
    return areaVars[areaId];
  }

  var RESERVED_VARS = new Set(['amount','tipper','username','message','months','streak',
    'gifted','bits','raiders','viewerCount','tier','formattedAmount','now']);

  function interpolate(template, ev, vars) {
    return String(template).replace(/\\{\\$(\\w+)\\}/g, function (_, key) {
      if (ev && ev[key] !== undefined) return String(ev[key]);
      if (vars && vars[key] !== undefined) return String(vars[key]);
      return '';
    });
  }

  function evalExpr(expr, ev, vars) {
    if (expr === null || expr === undefined) return 0;
    var s = String(expr).trim();
    var m = s.match(/^\\{\\$(\\w+)\\}$/);
    if (m) {
      var key = m[1];
      if (ev && ev[key] !== undefined) return Number(ev[key]) || 0;
      if (vars && vars[key] !== undefined) return Number(vars[key]) || 0;
      return 0;
    }
    var n = Number(s);
    return isNaN(n) ? 0 : n;
  }

  function executeLogicNode(node, areaId, ev, vars) {
    if (node.type === 'set-var') {
      var name = node.data.variable;
      if (name && !RESERVED_VARS.has(name)) vars[name] = interpolate(node.data.value || '', ev, vars);
    } else if (node.type === 'reset-var') {
      var rname = node.data.variable;
      if (rname && !RESERVED_VARS.has(rname)) delete vars[rname];
    } else if (node.type === 'math') {
      var a = evalExpr(node.data.a, ev, vars);
      var b = evalExpr(node.data.b, ev, vars);
      var op = node.data.operator;
      var result;
      if (op === '+') result = a + b;
      else if (op === '-') result = a - b;
      else if (op === '*') result = a * b;
      else if (op === '/') result = b !== 0 ? a / b : 0;
      else if (op === '%') result = b !== 0 ? a % b : 0;
      else if (op === 'min') result = Math.min(a, b);
      else if (op === 'max') result = Math.max(a, b);
      else result = 0;
      vars['$mathResult_' + node.id] = result;
    } else if (node.type === 'compare') {
      var ca = evalExpr(node.data.a, ev, vars);
      var cb = evalExpr(node.data.b, ev, vars);
      var cop = node.data.operator;
      var pass;
      if (cop === '>') pass = ca > cb;
      else if (cop === '>=') pass = ca >= cb;
      else if (cop === '<') pass = ca < cb;
      else if (cop === '<=') pass = ca <= cb;
      else if (cop === '==') pass = ca == cb;
      else if (cop === '!=') pass = ca != cb;
      else pass = false;
      return { branch: pass ? 'true' : 'false' };
    } else if (node.type === 'clamp') {
      var cv = evalExpr(node.data.value, ev, vars);
      var cmin = evalExpr(node.data.min, ev, vars);
      var cmax = evalExpr(node.data.max, ev, vars);
      vars['$clampResult_' + node.id] = Math.min(Math.max(cv, cmin), cmax);
    } else if (node.type === 'random') {
      var rmin = Number(node.data.min) || 0;
      var rmax = Number(node.data.max) || 1;
      var rval = Math.random() * (rmax - rmin) + rmin;
      vars['$randomResult_' + node.id] = node.data.integer ? Math.floor(rval) : rval;
    } else if (node.type === 'str-format') {
      vars['$strFormatResult_' + node.id] = interpolate(node.data.template || '', ev, vars);
    } else if (node.type === 'to-number') {
      vars['$toNumberResult_' + node.id] = parseFloat(interpolate(node.data.value || '', ev, vars)) || 0;
    } else if (node.type === 'to-string') {
      vars['$toStringResult_' + node.id] = evalExpr(node.data.value, ev, vars).toFixed(Number(node.data.decimals) || 0);
    }
    return null;
  }

  var LOGIC_NODE_TYPES = new Set(['set-var','get-var','reset-var','math','compare',
    'clamp','random','str-format','to-number','to-string','condition','delay']);

  function applyModifiers(el, effects) {
    if (!effects) return;
    if (typeof effects.opacity === 'number' && effects.opacity < 1) el.style.opacity = String(effects.opacity);
    if (effects.shadow && effects.shadow.enabled) {
      var x = Number(effects.shadow.x) || 0, y = Number(effects.shadow.y) || 0;
      var blur = Number(effects.shadow.blur) || 8, op = effects.shadow.opacity !== undefined ? Number(effects.shadow.opacity) : 0.5;
      var color = String(effects.shadow.color || '#000000');
      var r = parseInt(color.slice(1,3),16), g = parseInt(color.slice(3,5),16), b = parseInt(color.slice(5,7),16);
      el.style.filter = 'drop-shadow(' + x + 'px ' + y + 'px ' + blur + 'px rgba(' + r + ',' + g + ',' + b + ',' + op + '))';
    }
    if (effects.animation && effects.animation.enabled) {
      el.classList.add('animate__animated', 'animate__' + (effects.animation.name || 'bounce'));
      el.style.animationDuration = (Number(effects.animation.duration) || 1) + 's';
      var delay = Number(effects.animation.delay);
      if (delay) el.style.animationDelay = delay + 's';
      var repeat = Number(effects.animation.repeat);
      el.style.animationIterationCount = (!isNaN(repeat) && repeat === 0) ? 'infinite' : String(isNaN(repeat) ? 1 : repeat);
    }
  }

  function buildElementEl(el, parentId, eventData, vars) {
    var layout = (LAYOUTS[parentId] && LAYOUTS[parentId][el.id]) || { x: 0, y: 0, w: 50, h: 50, z: 0 };
    var div = document.createElement('div');
    div.className = 'content-item';
    div.dataset.elementId = el.id;
    div.style.cssText = 'left:' + layout.x + '%;top:' + layout.y + '%;width:' + layout.w + '%;height:' + layout.h + '%;z-index:' + (layout.z || 0) + ';';

    if (el.type === 'image' || el.type === 'gif') {
      var img = document.createElement('img');
      img.src = el.src || '';
      img.alt = '';
      div.appendChild(img);
    } else if (el.type === 'text') {
      var textDiv = document.createElement('div');
      textDiv.className = 'text-content';
      textDiv.textContent = interpolate(el.content || '', eventData, vars);
      if (el.fontSize) textDiv.style.fontSize = el.fontSize + 'px';
      if (el.fontFamily) textDiv.style.fontFamily = el.fontFamily;
      if (el.fontWeight) textDiv.style.fontWeight = String(el.fontWeight);
      if (el.textColor) textDiv.style.color = el.textColor;
      div.appendChild(textDiv);
    } else if (el.type === 'color') {
      div.style.backgroundColor = el.fillColor || '#000000';
    } else if (el.type === 'video') {
      var vid = document.createElement('video');
      vid.src = el.src || '';
      vid.volume = el.volume !== undefined ? Number(el.volume) : 1;
      vid.autoplay = el.autoplay !== false;
      vid.loop = !!el.loop;
      vid.muted = !!el.muted;
      div.appendChild(vid);
    }

    applyModifiers(div, el.effects);
    return div;
  }

  function buildContainerEl(node, areaId, eventData, vars) {
    var layout = (LAYOUTS[areaId] && LAYOUTS[areaId][node.id]) || { x: 0, y: 0, w: 100, h: 100, z: 0 };
    var div = document.createElement('div');
    div.className = 'content-item';
    div.style.cssText = 'left:' + layout.x + '%;top:' + layout.y + '%;width:' + layout.w + '%;height:' + layout.h + '%;z-index:' + (layout.z || 0) + ';overflow:hidden;';
    var children = ELEMENTS[node.id] || [];
    children.forEach(function (el) { div.appendChild(buildElementEl(el, node.id, eventData, vars)); });
    return div;
  }

  function executeGraph(areaId, triggerNodeId, ev) {
    var g = GRAPHS[areaId];
    if (!g) return null;
    var nodes = g.nodes, edges = g.edges;
    var byId = {};
    nodes.forEach(function (n) { byId[n.id] = n; });

    var trigger = byId[triggerNodeId] || null;
    if (!trigger) return null;

    var vars = getAreaVars(areaId);
    var transitionIn = null, transitionOut = null, lifecycleDuration = null;
    var lifecycleNode = null;
    var audioNodes = [];
    var delayMs = 0;
    var visited = {};
    var currentId = trigger.id;

    while (true) {
      if (visited[currentId]) break;
      visited[currentId] = true;
      var outs = outEdges(edges, currentId).filter(function(e) { return e.targetHandle !== 'content'; });
      if (!outs.length) break;

      var prev = byId[currentId];
      var next;
      if (prev && (prev.type === 'compare' || prev.type === 'condition')) {
        var logicResult = executeLogicNode(prev, areaId, ev, vars);
        var branch = logicResult ? logicResult.branch : 'true';
        var branchEdge = outs.filter(function(e) { return e.sourceHandle === branch; })[0] || outs[0];
        next = byId[branchEdge.target];
      } else {
        next = byId[outs[0].target];
      }
      if (!next) break;
      currentId = next.id;

      if (LOGIC_NODE_TYPES.has(next.type) && next.type !== 'compare' && next.type !== 'condition') {
        if (next.type === 'delay') {
          delayMs += (Number(next.data.duration) || 0) * 1000;
        } else {
          executeLogicNode(next, areaId, ev, vars);
        }
      } else if (next.type === 'fade-in') {
        transitionIn = { type: 'fade', duration: Number(next.data.duration) || 0.5 };
      } else if (next.type === 'slide-in') {
        transitionIn = { type: 'slide', duration: Number(next.data.duration) || 0.5, direction: next.data.direction || 'left' };
      } else if (next.type === 'fade-out') {
        transitionOut = { type: 'fade', duration: Number(next.data.duration) || 0.5 };
      } else if (next.type === 'transient' || next.type === 'persistent') {
        lifecycleNode = next;
        lifecycleDuration = next.type === 'transient' ? Number(next.data.duration) || 3 : null;
      } else if (next.type === 'audio') {
        if (next.data.src) audioNodes.push(next);
      }
    }

    return { areaId: areaId, lifecycleNode: lifecycleNode, vars: vars, transitionIn: transitionIn, transitionOut: transitionOut, lifecycleDuration: lifecycleDuration, audioNodes: audioNodes, delayMs: delayMs };
  }

  function findEventTrigger(areaId, eventType) {
    var g = GRAPHS[areaId];
    if (!g) return null;
    for (var i = 0; i < g.nodes.length; i++) {
      if (g.nodes[i].type === 'on-event' && g.nodes[i].data.event === eventType) return g.nodes[i].id;
    }
    return null;
  }

  function playAudio(cmd) {
    (cmd.audioNodes || []).forEach(function(node) {
      if (!node.data.src) return;
      var audio = new Audio(node.data.src);
      audio.volume = Math.max(0, Math.min(1, Number(node.data.volume) || 1));
      audio.play().catch(function(){});
    });
  }

  function applyIn(el, transition) {
    if (!transition) return;
    var d = transition.duration + 's';
    if (transition.type === 'fade') {
      el.style.animation = 'alchemy-fade-in ' + d + ' ease forwards';
    } else if (transition.type === 'slide') {
      var names = { left: 'alchemy-slide-left', right: 'alchemy-slide-right', top: 'alchemy-slide-top', bottom: 'alchemy-slide-bottom' };
      el.style.animation = (names[(transition.direction || 'left').toLowerCase()] || 'alchemy-slide-left') + ' ' + d + ' ease forwards';
    }
  }

  function applyOut(el, transition, cb) {
    if (!transition) { cb(); return; }
    el.style.animation = 'alchemy-fade-out ' + transition.duration + 's ease forwards';
    setTimeout(cb, transition.duration * 1000);
  }

  function renderArea(cmd, eventData) {
    playAudio(cmd);
    var areaEl = document.getElementById('area-' + cmd.areaId);
    if (!areaEl || !cmd.lifecycleNode) {
      console.log('[Alchemy] renderArea skip — areaEl:', !!areaEl, 'lifecycleNode:', !!cmd.lifecycleNode);
      return;
    }

    if (activeTimers[cmd.areaId]) { clearTimeout(activeTimers[cmd.areaId]); delete activeTimers[cmd.areaId]; }

    areaEl.innerHTML = '';
    var wrapper = document.createElement('div');
    wrapper.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';

    var elements = ELEMENTS[cmd.lifecycleNode.id] || [];
    console.log('[Alchemy] renderArea:', cmd.areaId, 'lifecycleNode:', cmd.lifecycleNode.id, 'elements:', elements.length);
    elements.forEach(function (el) { wrapper.appendChild(buildElementEl(el, cmd.areaId, eventData, cmd.vars)); });

    contentEdges(GRAPHS[cmd.areaId].edges, cmd.lifecycleNode.id).forEach(function(e) {
      var byId = {};
      GRAPHS[cmd.areaId].nodes.forEach(function(n) { byId[n.id] = n; });
      var cn = byId[e.source];
      if (cn && cn.type === 'container') wrapper.appendChild(buildContainerEl(cn, cmd.areaId, eventData, cmd.vars));
    });

    areaEl.appendChild(wrapper);
    applyIn(wrapper, cmd.transitionIn);

    if (cmd.lifecycleDuration !== null) {
      activeTimers[cmd.areaId] = setTimeout(function () {
        applyOut(wrapper, cmd.transitionOut, function () {
          if (areaEl.contains(wrapper)) areaEl.removeChild(wrapper);
        });
      }, cmd.lifecycleDuration * 1000);
    }
  }

  function normalizeEvent(detail) {
    if (!detail) return null;
    var eventType = detail.type || detail.listener;
    if (!eventType) return null;
    var eventData = detail.event || detail;
    var norm = {};
    for (var k in eventData) { if (eventData.hasOwnProperty(k)) norm[k] = eventData[k]; }
    if (eventType === 'donation') {
      if (norm.from && !norm.tipper) norm.tipper = norm.from;
      if (norm.name && !norm.tipper) norm.tipper = norm.name;
      if (norm.from && !norm.username) norm.username = norm.from;
    } else {
      if (norm.name && !norm.username) norm.username = norm.name;
    }
    var TYPE_MAP = {
      'donation-latest': 'donation', 'follower-latest': 'follow',
      'subscriber-latest': 'subscription', 'cheer-latest': 'bits',
      'superchat-latest': 'superchat', 'raid-latest': 'raid', 'merch-latest': 'merch'
    };
    return { eventType: TYPE_MAP[eventType] || eventType, eventData: norm };
  }

  function fireInitTriggers() {
    AREAS.forEach(function (area) {
      var triggerId = findEventTrigger(area.id, 'init');
      console.log('[Alchemy] init trigger for', area.name + ':', triggerId || 'none');
      if (!triggerId) return;
      var cmd = executeGraph(area.id, triggerId, {});
      if (cmd) renderArea(cmd, {});
    });
  }

  function setupTimers() {
    AREAS.forEach(function (area) {
      var g = GRAPHS[area.id];
      if (!g) return;
      g.nodes.forEach(function (node) {
        if (node.type !== 'on-timer') return;
        var intervalMs = Math.max(1000, (Number(node.data.interval) || 60) * 1000);
        var nodeId = node.id;
        setInterval(function () {
          var ev = { now: Date.now() };
          var cmd = executeGraph(area.id, nodeId, ev);
          if (!cmd) return;
          if (cmd.delayMs > 0) {
            setTimeout(function() { renderArea(cmd, ev); }, cmd.delayMs);
          } else {
            renderArea(cmd, ev);
          }
        }, intervalMs);
      });
    });
  }

  document.addEventListener('onEventReceived', function (obj) {
    var detail = obj.detail || obj;
    console.log('[Alchemy] onEventReceived:', JSON.stringify(detail));
    var parsed = normalizeEvent(detail);
    if (!parsed) { console.log('[Alchemy] could not parse event'); return; }
    console.log('[Alchemy] eventType:', parsed.eventType, 'tipper:', parsed.eventData.tipper, 'amount:', parsed.eventData.amount);
    AREAS.forEach(function (area) {
      var triggerId = findEventTrigger(area.id, parsed.eventType);
      if (!triggerId) { console.log('[Alchemy] no trigger for', parsed.eventType, 'in', area.name); return; }
      var cmd = executeGraph(area.id, triggerId, parsed.eventData);
      if (!cmd) return;
      if (cmd.delayMs > 0) {
        setTimeout(function() { renderArea(cmd, parsed.eventData); }, cmd.delayMs);
      } else {
        renderArea(cmd, parsed.eventData);
      }
    });
  });

  var initDone = false;
  document.addEventListener('onWidgetLoad', function () {
    if (initDone) return;
    initDone = true;
    console.log('[Alchemy] onWidgetLoad fired');
    fireInitTriggers();
    setupTimers();
  });

  // Fire init immediately in case onWidgetLoad already fired or won't fire
  fireInitTriggers();
  setupTimers();
})();`
}
